import json, subprocess, datetime

def gh_api(path):
    return json.loads(subprocess.check_output(['gh','api',path], text=True))

today=datetime.date(2026,3,3)
start=(today-datetime.timedelta(days=7)).isoformat()
recent=gh_api(f'search/repositories?q=created:>={start}+archived:false&sort=stars&order=desc&per_page=20')['items']
active_since=(today-datetime.timedelta(days=180)).isoformat()
cum=gh_api(f'search/repositories?q=stars:>1+archived:false+pushed:>={active_since}&sort=stars&order=desc&per_page=30')['items']
recent5=recent[:5]
cum5=[]
seen={r['full_name'] for r in recent5}
for r in cum:
    if r['full_name'] in seen: continue
    cum5.append(r)
    seen.add(r['full_name'])
    if len(cum5)==5: break

def row(r):
    print('|'.join([
        r['full_name'],str(r['stargazers_count']),r['created_at'][:10],r['pushed_at'][:10],r.get('language') or '-', (r.get('description') or '').replace('\n',' ')[:140],r['html_url']
    ]))
print('RECENT')
for r in recent5: row(r)
print('CUM')
for r in cum5: row(r)
